def level_allows(effective, msg_level):
    # effective is current log level filter, msg_level is level of message
    # off means no logs, error means only error, etc
    eff = LEVEL_ORDER.get(effective, 3)
    msg = LEVEL_ORDER.get(msg_level, 3)
    if eff == 0:
        return False
    return msg <= eff

def log_msg(effective, lvl, msg, also_stderr=True):
    if level_allows(effective, lvl):
        # original prints like [INFO  svd2rust] ... to stderr
        prefix = f"[{lvl.upper()}  svd2rust] {msg}"
        # Use stderr
        print(prefix, file=sys.stderr)

def parse_ident_format_str(s):
    # returns dict or None
    if not s:
        return None
    parts = s.split(":")
    if len(parts) == 1:
        # only type
        t = parts[0]
        if t not in IDENT_TYPES:
            return None
        return {"type":t, "prefix":"", "case":None, "suffix":""}
    elif len(parts) == 2:
        t, c = parts
        if t not in IDENT_TYPES:
            return None
        # c should be case
        if c not in CASE_CHOICES and c not in ["pascal","snake","constant","unchanged","p","c","s",""]:
            # treat as invalid -> ignore
            return None
        # map case
        return {"type":t, "prefix":"", "case":c, "suffix":""}
    elif len(parts) == 3:
        t, pre, c = parts
        if t not in IDENT_TYPES:
            return None
        if c not in CASE_CHOICES and c not in ["pascal","snake","constant","unchanged","p","c","s",""]:
            return None
        return {"type":t, "prefix":pre, "case":c, "suffix":""}
    elif len(parts) == 4:
        t, pre, c, suf = parts
        if t not in IDENT_TYPES:
            return None
        if c not in CASE_CHOICES and c not in ["pascal","snake","constant","unchanged","p","c","s",""]:
            return None
        return {"type":t, "prefix":pre, "case":c, "suffix":suf}
    else:
        # more than 4?
        return None

def convert_case(name, case):
    if case is None or case == "" or case == "unchanged":
        return name
    if case in ("pascal","p"):
        # PascalCase: split on _ - and capitalize
        # For TIMER0 -> Timer0
        # For simple upper, lower then capitalize
        parts = re.split(r'[_\-\s]+', name)
        out = ""
        for p in parts:
            if not p:
                continue
            out += p[0].upper() + p[1:].lower() if len(p)>1 else p.upper()
        return out
    if case in ("snake","s"):
        return name.lower().replace("-","_")
    if case in ("constant","c"):
        # constant is upper snake
        # convert to upper
        snake = name.lower().replace("-","_")
        # insert underscores before caps for camel? Simplify just upper
        return snake.upper()
    return name

def apply_ident(name, ident_type, formats):
    fmt = formats.get(ident_type)
    if not fmt:
        # use default per debug dump defaults
        # Provide defaults for known types
        defaults = {
            "peripheral": "pascal",
            "peripheral_singleton": "snake",
            "peripheral_spec": "pascal",
            "peripheral_mod": "snake",
            "peripheral_feature": "snake",
            "register": "pascal",
            "register_mod": "snake",
            "register_spec": "pascal",
            "register_accessor": "snake",
            "field_accessor": "snake",
            "field_reader": "pascal",
            "field_writer": "pascal",
            "interrupt": "unchanged",
            "cluster": "pascal",
            "cluster_mod": "snake",
            "cluster_accessor": "snake",
            "enum_name": "pascal",
            "enum_value": "pascal",
            "enum_read_name": "pascal",
            "enum_write_name": "pascal",
            "enum_value_accessor": "snake",
        }
        case = defaults.get(ident_type)
        if case is None:
            return name
        # need prefix/suffix defaults
        suffix_map = {
            "peripheral_spec": "Spec",
            "register_spec": "Spec",
            "field_reader": "R",
            "field_writer": "W",
            "enum_write_name": "WO",
        }
        prefix=""
        suffix=suffix_map.get(ident_type,"")
        return prefix + convert_case(name, case) + suffix
    # custom
    prefix = fmt.get("prefix","")
    case = fmt.get("case")
    suffix = fmt.get("suffix","")
    # if case None, use default?
    if case is None or case == "":
        # use default case for that type? But custom prefix with empty case means unchanged?
        converted = name
    else:
        converted = convert_case(name, case)
    return prefix + converted + suffix

