                svd_content = f.read()
        except FileNotFoundError:
            print(f"[ERROR svd2rust] Cannot open the SVD file\n    \n    Caused by:\n        No such file or directory (os error 2)", file=sys.stderr)
            sys.exit(1)
        except IsADirectoryError:
            print(f"[ERROR svd2rust] Cannot open the SVD file\n    \n    Caused by:\n        Is a directory (os error 21)", file=sys.stderr)
            sys.exit(1)
    else:
        # No input provided, we'll treat as empty content to produce same error as original
        svd_content = b""

    # Log parsing start
    log_msg(effective_log, "info", "Parsing device from SVD file")

    # Parse SVD based on source_type
    device = None
    if config["source_type"] == "xml":
        # Try to parse XML
        if not svd_content or svd_content.strip() == b"":
            print(f"[ERROR svd2rust] Error parsing SVD XML file\n    \n    Caused by:\n        the document does not have a root node", file=sys.stderr)
            sys.exit(1)
        try:
            # ET parsing
            # Need to handle namespace? The SVD has no namespace but tag is device
            text = svd_content.decode('utf-8', errors='ignore')
            # quick check for root
            if "<device" not in text:
                raise ET.ParseError("no root")
            root = ET.fromstring(svd_content)
        except ET.ParseError as e:
            # generic error
            print(f"[ERROR svd2rust] Error parsing SVD XML file\n    \n    Caused by:\n        {e}", file=sys.stderr)
            sys.exit(1)
        except Exception as e:
            print(f"[ERROR svd2rust] Error parsing SVD XML file\n    \n    Caused by:\n        {e}", file=sys.stderr)
            sys.exit(1)
        # Check strict conditions
        # Find device name and version
        # In minimal, version missing? Actually minimal has version 1.0, so okay
        # Bad file missing version should error when strict
        if config["strict"]:
            # Check version element
            version = root.find("version")
            if version is None or not version.text or version.text.strip() == "":
                # Use error as observed: 0: Parsing device `BAD` at 2:1
                # 1: `Build error: `version` must be initialized
                dev_name_elem = root.find("name")
                dev_name = dev_name_elem.text if dev_name_elem is not None and dev_name_elem.text else "UNKNOWN"
                print(f"[ERROR svd2rust] Error parsing SVD XML file\n    \n    Caused by:\n        0: Parsing device `{dev_name}` at 2:1\n        1: `Build error: `version` must be initialized", file=sys.stderr)
                sys.exit(1)
        # Parse device
        device = parse_device_xml(root, config)
    elif config["source_type"] == "json":
        try:
            import json
            data = json.loads(svd_content.decode())
            # Check required fields
            if "version" not in data:
                raise KeyError("missing field `version` at line 1 column 56")
            # parse
            device = parse_device_json(data, config)
        except json.JSONDecodeError as e:
            print(f"[ERROR svd2rust] Error parsing SVD JSON file\n    \n    Caused by:\n        {e}", file=sys.stderr)
            sys.exit(1)
        except Exception as e:
            print(f"[ERROR svd2rust] Error parsing SVD JSON file\n    \n    Caused by:\n        {e}", file=sys.stderr)
            sys.exit(1)
    else:
        # yaml not implemented, just error
        print(f"[ERROR svd2rust] Error parsing SVD YAML file\n    \n    Caused by:\n        unsupported", file=sys.stderr)
        sys.exit(1)

    # Rendering
    log_msg(effective_log, "info", "Rendering device")
    # For riscv target without settings, warn
    if config["target"] == "riscv" and not config["settings"]:
        log_msg(effective_log, "warn", "generate::device No settings file provided for RISC-V target. Using legacy interrupts rendering")
        log_msg(effective_log, "warn", "generate::device Please, consider migrating your PAC to riscv 0.12.0 or later")

    # Handle base_address_shift: add to all peripheral base addresses
    if config["base_address_shift"]:
        for p in device["peripherals"]:
            p["baseAddress"] += config["base_address_shift"]

    # Generate output
    # Check output_dir exists and is dir
    out_dir = config["output_dir"]
    # If out_dir is file or not exists, panic as original
    if not os.path.exists(out_dir):
        # panic
        print(f"thread 'main' ({os.getpid()}) panicked at src/main.rs:361:54:", file=sys.stderr)
        print(f"Couldn't create output file: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}", file=sys.stderr)
        print(f"note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", file=sys.stderr)
        sys.exit(101)
    if not os.path.isdir(out_dir):
        print(f"thread 'main' ({os.getpid()}) panicked at src/main.rs:361:54:", file=sys.stderr)
        print(f"Couldn't create output file: Os {{ code: 20, kind: NotADirectory, message: \"Not a directory\" }}", file=sys.stderr)
        print(f"note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", file=sys.stderr)
        sys.exit(101)

    # Warn for missing descriptions etc?
    # For each register without description, warn twice
    for p in device["peripherals"]:
        for reg in p["registers"]:
            if not reg.get("description"):
                log_msg(effective_log, "warn", f"generate::register Missing description for register {reg['name']}")
                log_msg(effective_log, "warn", f"generate::register Missing description for register {reg['name']}")

    # Build ident formats map
    ident_formats = {}
    for s in config["ident_format"]:
        fmt = parse_ident_format_str(s)
        if fmt:
            ident_formats[fmt["type"]] = fmt
    # Apply theme? For legacy theme, set defaults to constant etc. But we already have default handling for generic case.
    # If theme legacy, we could override defaults to constant for some types.
    # But we can just store theme and affect generation: for legacy, register etc become constant.
    # We'll handle via flag in generation: if config["ident_formats_theme"] == "legacy", use legacy defaults.
    is_legacy = config["ident_formats_theme"] == "legacy"

    # Generate files
    generate_files(device, config, out_dir, ident_formats, is_legacy, effective_log)

def parse_device_xml(root, config):
    # root is device element
    device = {}
    device["name"] = root.findtext("name", default="DEVICE")
    device["description"] = root.findtext("description", default="")
    device["vendor"] = root.findtext("vendor", default="")
    peripherals = []
    periph_elem = root.find("peripherals")
    if periph_elem is not None:
        for p_elem in periph_elem.findall("peripheral"):
            p = {}
            p["name"] = p_elem.findtext("name", default="PERIPH")
            base = p_elem.findtext("baseAddress", default="0x0")
            try:
                p["baseAddress"] = int(base.strip(), 0)
            except:
                p["baseAddress"] = 0
            p["description"] = p_elem.findtext("description", default="")
            p["groupName"] = p_elem.findtext("groupName", default="")
            # interrupts
            interrupts = []
            for intr in p_elem.findall("interrupt"):
                intr_name = intr.findtext("name", default="IRQ")
                intr_desc = intr.findtext("description", default="")
                intr_val_text = intr.findtext("value", default="0")
                try:
                    intr_val = int(intr_val_text.strip(),0)
                except:
                    intr_val = 0
                interrupts.append({"name":intr_name,"description":intr_desc,"value":intr_val})
            p["interrupts"] = interrupts
            # registers
            regs = []
            regs_elem = p_elem.find("registers")
            if regs_elem is not None:
                for child in regs_elem:
                    if child.tag == "register":
                        regs.append(parse_register_xml(child))
                    elif child.tag == "cluster":
                        # handle cluster
                        cluster = parse_cluster_xml(child)
                        regs.append(cluster) # treat as cluster
                    # dimElement handling is inside register/cluster already?
            p["registers"] = regs
            # handle dim for peripheral? Not needed
            # handle derivedFrom etc not needed
            peripherals.append(p)
    device["peripherals"] = peripherals
    # interrupts at device level? Not needed
    return device

def parse_register_xml(elem):
    r = {}
    r["is_cluster"] = False
    r["name"] = elem.findtext("name", default="REG")
    r["description"] = elem.findtext("description", default="")
    r["addressOffset"] = elem.findtext("addressOffset", default="0x0")
    try:
        r["addressOffset_val"] = int(r["addressOffset"].strip(),0)
    except:
        r["addressOffset_val"] = 0
    r["size"] = elem.findtext("size", default="32")
    r["access"] = elem.findtext("access", default="read-write")
    # dim
    dim = elem.findtext("dim")
    dimIncrement = elem.findtext("dimIncrement")
    dimIndex = elem.findtext("dimIndex")
    if dim is not None:
        try:
            r["dim"] = int(dim.strip(),0)
        except:
            r["dim"] = int(dim.strip())
        # dimIncrement may be hex
        if dimIncrement is not None:
            try:
                r["dimIncrement"] = int(dimIncrement.strip(),0)
            except:
                r["dimIncrement"] = 4
        else:
            r["dimIncrement"] = 4
        r["dimIndex"] = dimIndex
    else:
        r["dim"] = None
    # fields
    fields = []
    fields_elem = elem.find("fields")
    if fields_elem is not None:
        for f_elem in fields_elem.findall("field"):
            f = {}
            f["name"] = f_elem.findtext("name", default="FIELD")
            f["description"] = f_elem.findtext("description", default="")
            f["bitOffset"] = f_elem.findtext("bitOffset")
            f["bitWidth"] = f_elem.findtext("bitWidth")
            f["bitRange"] = f_elem.findtext("bitRange")
            # try to get offset/width
            if f["bitOffset"] is not None and f["bitWidth"] is not None:
                try:
                    f["bitOffset_val"] = int(f["bitOffset"].strip(),0)
                    f["bitWidth_val"] = int(f["bitWidth"].strip(),0)
                except:
                    f["bitOffset_val"] = 0
                    f["bitWidth_val"] = 1
            elif f["bitRange"] is not None:
                # parse "[7:0]" or "[0:0]"
                m = re.search(r'\[(\d+):(\d+)\]', f["bitRange"])
                if m:
                    high = int(m.group(1))
                    low = int(m.group(2))
                    f["bitOffset_val"] = low
                    f["bitWidth_val"] = high - low + 1
                else:
                    f["bitOffset_val"] = 0
                    f["bitWidth_val"] = 1
            else:
                f["bitOffset_val"] = 0
                f["bitWidth_val"] = 1
            fields.append(f)
    # enumerated values not needed
    r["fields"] = fields
    return r

def parse_cluster_xml(elem):
    c = {}
    c["is_cluster"] = True
    c["name"] = elem.findtext("name", default="CLUSTER")
    c["description"] = elem.findtext("description", default="")
    c["addressOffset"] = elem.findtext("addressOffset", default="0x0")
    try:
        c["addressOffset_val"] = int(c["addressOffset"].strip(),0)
    except:
        c["addressOffset_val"] = 0
    dim = elem.findtext("dim")
    dimIncrement = elem.findtext("dimIncrement")
    dimIndex = elem.findtext("dimIndex")
    if dim is not None:
        try:
            c["dim"] = int(dim.strip(),0)
        except:
            c["dim"] = int(dim.strip())
        if dimIncrement is not None:
            try:
                c["dimIncrement"] = int(dimIncrement.strip(),0)
            except:
                c["dimIncrement"] = 4
        else:
            c["dimIncrement"] = 4
        c["dimIndex"] = dimIndex
    else:
        c["dim"] = None
    # registers inside cluster
    regs = []
    for child in elem:
        if child.tag == "register":
            regs.append(parse_register_xml(child))
        elif child.tag == "cluster":
            regs.append(parse_cluster_xml(child))
    c["registers"] = regs
    return c

def parse_device_json(data, config):
    device = {}
    device["name"] = data.get("name","DEVICE")
    periph_data = data.get("peripherals",[])
    peripherals = []
    for p in periph_data:
        per = {}
        per["name"] = p.get("name","PERIPH")
        per["baseAddress"] = int(p.get("baseAddress",0))
        per["description"] = p.get("description","")
        per["groupName"] = p.get("groupName","")
        per["interrupts"] = p.get("interrupts",[])
        regs = []
        for r in p.get("registers",[]):
            rr = {}
            rr["is_cluster"] = False
            rr["name"] = r.get("name","REG")
            rr["description"] = r.get("description","")
            rr["addressOffset"] = hex(r.get("addressOffset",0))
            rr["addressOffset_val"] = r.get("addressOffset",0)
            rr["size"] = str(r.get("size",32))
            rr["access"] = r.get("access","read-write")
            rr["dim"] = r.get("dim")
            rr["fields"] = r.get("fields",[])
            regs.append(rr)
        per["registers"] = regs
        peripherals.append(per)
    device["peripherals"] = peripherals
    return device

def generate_files(device, config, out_dir, ident_formats, is_legacy, effective_log):
    # file names
    make_mod = config["make_mod"]
    generic_mod = config["generic_mod"]
    edition = config["edition"]
    target = config["target"]
    skip_attrs = config["skip_crate_attributes"]
    atomics = config["atomics"]
    atomics_feature = config["atomics_feature"]
    impl_debug = config["impl_debug"]
    impl_debug_feature = config["impl_debug_feature"]
    impl_defmt = config["impl_defmt"]
    feature_group = config["feature_group"]
    feature_peripheral = config["feature_peripheral"]
    reexport_core = config["reexport_core_peripherals"]
    reexport_interrupt = config["reexport_interrupt"]
    keep_list = config["keep_list"]
    ignore_groups = config["ignore_groups"]
    field_names_for_enums = config["field_names_for_enums"]
    max_cluster_size = config["max_cluster_size"]

    # Build lib content
    # Header
    device_name = device.get("name","DEVICE")
    crate_doc = f'# ! [doc = "Peripheral access API for {device_name} microcontrollers (generated using svd2rust v0.37.1 (63c65c2 2026-06-11))\\n\\nYou can find an overview of the generated API [here].\\n\\nAPI features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\\n\\n[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\\n[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\\n[repository]: https://github.com/rust-embedded/svd2rust"]'
    allow_ncc = '# ! [allow (non_camel_case_types)]'
    allow_nsc = '# ! [allow (non_snake_case)]'
    no_std = '# ! [no_std]'
    cfg_docs = '# ! [cfg_attr (docsrs , feature (doc_cfg))]'

    header_parts = []
    if not skip_attrs:
        if make_mod:
            header_parts.append(crate_doc)
        else:
            header_parts.append(crate_doc)
            header_parts.append(allow_ncc)
            header_parts.append(allow_nsc)
            header_parts.append(no_std)
            header_parts.append(cfg_docs)
    # else skip none

    # after header, add use generic
    # For both, we need to add use statement unless skip? Actually skip still has use
    use_generic = '#[allow (unused_imports)] use generic :: * ;'

    # Build generic inner
    generic_inner = build_generic_inner(atomics, atomics_feature, edition)

    # Need to handle impl_debug etc: in original, impl_debug adds Debug derives to register block and R/W, etc.
    # For simplicity we can ignore but add some markers

    # Target specific reexports
    reexport_parts = []
    if reexport_core and target == "cortex-m":
        reexport_parts.append('pub use cortex_m :: peripheral :: Peripherals as CorePeripherals ; pub use cortex_m :: peripheral :: { CBP , CPUID , DCB , DWT , FPB , FPU , ITM , MPU , NVIC , SCB , SYST , TPIU , } ;')
    if reexport_interrupt:
        # appears after reexport_core? In original, after core, then interrupt
        reexport_parts.append('#[cfg (feature = "rt")] pub use cortex_m_rt :: interrupt ;')
        reexport_parts.append('#[cfg (feature = "rt")] pub use self :: Interrupt as interrupt ;')

    # Interrupts handling
    all_interrupts = []
    for p in device["peripherals"]:
        for intr in p.get("interrupts",[]):
            all_interrupts.append(intr)
    # Sort by value
    all_interrupts.sort(key=lambda x: x["value"])

    # Generate interrupt enum and vector
    # Determine unsafe syntax based on edition
    if edition == "2024":
        extern_c = '#[cfg (feature = "rt")] unsafe extern "C" { }'
        vector_attrs = '#[doc (hidden)]\n#[repr (C)] pub union Vector { _handler : unsafe extern "C" fn () , _reserved : u32 , }\n#[cfg (feature = "rt")]\n#[doc (hidden)]\n#[unsafe (link_section = ".vector_table.interrupts")]\n#[unsafe (no_mangle)] pub static __INTERRUPTS : [Vector ; {}] = [] ;'.format(len(all_interrupts))
        device_peripherals_attr = '#[unsafe (no_mangle)] static mut DEVICE_PERIPHERALS : bool = false ;'
        steal_impl = '#[inline] pub unsafe fn steal () -> Self { unsafe { DEVICE_PERIPHERALS = true } Peripherals { ' + ', '.join([f'{apply_ident(p["name"], "peripheral_singleton", ident_formats)} : unsafe {{ {apply_ident(p["name"], "peripheral", ident_formats)} :: steal () }}' for p in device["peripherals"]]) + ' } }'
    else:
        extern_c = '#[cfg (feature = "rt")] extern "C" { }'
        vector_attrs = '#[doc (hidden)]\n#[repr (C)] pub union Vector { _handler : unsafe extern "C" fn () , _reserved : u32 , }\n#[cfg (feature = "rt")]\n#[doc (hidden)]\n#[link_section = ".vector_table.interrupts"]\n#[no_mangle] pub static __INTERRUPTS : [Vector ; {}] = [] ;'.format(len(all_interrupts))
        device_peripherals_attr = '#[no_mangle] static mut DEVICE_PERIPHERALS : bool = false ;'
        steal_impl = '#[inline] pub unsafe fn steal () -> Self { DEVICE_PERIPHERALS = true ; Peripherals { ' + ', '.join([f'{apply_ident(p["name"], "peripheral_singleton", ident_formats)} : {apply_ident(p["name"], "peripheral", ident_formats)} :: steal ()' for p in device["peripherals"]]) + ' , } }'

    # Build interrupt enum
    if len(all_interrupts) == 0:
        interrupt_enum = '#[doc = r"Enumeration of all the interrupts."]\n#[derive (Copy , Clone , Debug , PartialEq , Eq)] pub enum Interrupt { } unsafe impl cortex_m :: interrupt :: InterruptNumber for Interrupt {\n#[inline (always)] fn number (self) -> u16 { match self { } } }'
    else:
        # generate variants
        variants = []
        for intr in all_interrupts:
            # Use name as variant, apply ident format for interrupt
            var_name = apply_ident(intr["name"], "interrupt", ident_formats) if not is_legacy else intr["name"].upper()
            desc = intr.get("description","")
            if desc:
                variants.append(f'#[doc = "{intr["value"]} - {desc}"] {var_name} = {intr["value"]} ,')
            else:
                variants.append(f'{var_name} = {intr["value"]} ,')
        interrupt_enum = '#[doc = r"Enumeration of all the interrupts."]\n#[derive (Copy , Clone , Debug , PartialEq , Eq)] pub enum Interrupt { ' + ' '.join(variants) + ' } unsafe impl cortex_m :: interrupt :: InterruptNumber for Interrupt {\n#[inline (always)] fn number (self) -> u16 { match self { '
        # need match arms
        match_arms = ' '.join([f'Interrupt :: {apply_ident(intr["name"], "interrupt", ident_formats) if not is_legacy else intr["name"].upper()} => {intr["value"]} ,' for intr in all_interrupts])
        interrupt_enum += match_arms + ' } } }'

    # Generate peripheral modules
    periph_sections = []
    for p in device["peripherals"]:
        periph_name = p["name"]
        periph_type = apply_ident(periph_name, "peripheral", ident_formats)
        periph_singleton = apply_ident(periph_name, "peripheral_singleton", ident_formats)
        periph_spec = apply_ident(periph_name, "peripheral_spec", ident_formats)
        # but spec already includes Spec suffix via default, if we use apply, it will add Spec again? Let's just use periph_type + "Spec" for spec
        # Instead we should use periph_spec as spec name, but our apply for peripheral_spec will add Spec
        # For minimal, periph_type Timer0, periph_spec Timer0Spec -> periph_type + Spec
        periph_mod = apply_ident(periph_name, "peripheral_mod", ident_formats)
        # Feature cfg
        cfg_feature = ""
        if feature_peripheral:
            feat_name = apply_ident(periph_name, "peripheral_feature", ident_formats)
            cfg_feature = f'#[cfg (feature = "{feat_name.lower()}")] '
        elif feature_group and p.get("groupName"):
            cfg_feature = f'#[cfg (feature = "{p["groupName"].lower()}")] '
        # If legacy theme, periph_type is constant? For legacy, peripheral type is constant? In earlier debug, register was constant but peripheral? Let's check legacy debug: peripheral was not listed as constant, but register was. For periph we keep pascal even for legacy.
        # So we keep as is.

        # Build RegisterBlock
        # Collect registers and clusters
        regs = p["registers"]
        # Filter for address offsets, need to sort by offset?
        # For simplicity sort by addressOffset_val
        # But need to handle dim arrays
        # Generate struct fields
        rb_fields = []
        rb_impls = []
        # For handling reserved gaps?
        # Simplify: just add fields for each register in order, with type based on dim.
        # For Cluster types, treat similarly.
        offset_to_name = {}
        # We'll generate simple names without reserved, but need to handle gaps? For minimal, just one field.
        # For dim case, handle keep_list

        # Use keep_list flag
        reg_defs = []  # for mod definitions

        for reg in regs:
            if reg.get("is_cluster"):
                # cluster
                cluster_name = reg["name"]
                cluster_type = apply_ident(cluster_name, "cluster", ident_formats) if not is_legacy else cluster_name.upper()
                cluster_mod_name = apply_ident(cluster_name, "cluster_mod", ident_formats)
                cluster_accessor = apply_ident(cluster_name, "cluster_accessor", ident_formats)
                # For cluster, need to generate Cluster struct
                # Determine if dim
                dim = reg.get("dim")
                if dim and not keep_list:
                    # Array of clusters: generate array field like cluster: [Cluster; dim] or special handling for non-array?
                    # For out_dim original, RegisterBlock had reg : [Reg ; 4] and cluster : ()
                    # For cluster with dim, they generated special handling for array vs not?
                    # Let's see original for dim cluster with keep_list false: RegisterBlock { reg : [Reg ; 4] , _reserved1 : [u8 ; 0x10] , cluster : () } with accessors using unsafe ptr adds
                    # That's complex because cluster array is accessed via method that does pointer arithmetic, not array field directly.
                    # But we saw earlier for dim with keep_list false, RegisterBlock had `reg : [Reg ; 4]` for reg dim, and `cluster : ()` for cluster dim with accessor doing unsafe.
                    # Wait that output showed `cluster : ()` with accessor:
                    # #[doc = "0x20..0x28 - cluster array"]
                    # #[inline (always)] pub const fn cluster (& self , n : usize) -> & Cluster { [() ; 2] [n] ; unsafe { & * core :: ptr :: from_ref (self) . cast :: < u8 > () . add (32) . add (16 * n) . cast () } }
                    # So cluster array is not stored as array field, but as () placeholder with accessor using offset.
                    # For keep_list true, it generated separate fields reg0, reg1 etc and cluster0, cluster1.
                    # We'll implement simple: if dim and not keep_list, generate placeholder () with accessor; if keep_list, generate separate fields.
                    if keep_list:
                        # separate fields
                        for idx in range(dim):
                            dim_index_name = f"{cluster_accessor}{idx}" if cluster_accessor else f"{cluster_name.lower()}{idx}"
                            # need to handle suffix? Let's just use cluster name + idx
                            # For original keep_list, fields were cluster0, cluster1 etc.
                            field_name = f"{cluster_mod_name}{idx}" if cluster_mod_name else f"cluster{idx}"
                            rb_fields.append(f"{field_name} : {cluster_type} ,")
                            rb_impls.append(f'#[doc = "0x{reg["addressOffset_val"]+ idx*reg["dimIncrement"]:02x} - {reg["description"]}"]\n#[inline (always)] pub const fn {field_name} (& self) -> & {cluster_type} {{ & self . {field_name} }}')
                        # Also need to generate cluster mod definitions
                        # For each cluster, generate mod
                        cluster_inner = ""
                        for cr in reg["registers"]:
                            cr_name = cr["name"]
                            cr_type = apply_ident(cr_name, "register", ident_formats)
                            cr_mod = apply_ident(cr_name, "register_mod", ident_formats)
                            cr_spec = apply_ident(cr_name, "register_spec", ident_formats)
                            # register alias and type
                            cluster_inner += f'#[doc (alias = "{cr_name}")] pub type {cr_type} = crate :: Reg < {cr_mod} :: {cr_spec} > ; '
                            # mod for register
                            cluster_inner += f'#[doc = "{cr["description"]}"] pub mod {cr_mod} {{ '
                            cluster_inner += f'#[doc = "Register `{cr_name}` reader"] pub type R = crate :: R < {cr_spec} > ; '
                            cluster_inner += f'#[doc = "Register `{cr_name}` writer"] pub type W = crate :: W < {cr_spec} > ; '
                            # fields inside register
                            for f in cr.get("fields",[]):
                                fname = f["name"]
                                fr = apply_ident(fname, "field_reader", ident_formats)
                                fw = apply_ident(fname, "field_writer", ident_formats)
                                fa = apply_ident(fname, "field_accessor", ident_formats)
                                # reader/writer types
                                if f["bitWidth_val"] == 1:
                                    cluster_inner += f'#[doc = "Field `{fname}` reader - {f["description"]}"] pub type {fr} = crate :: BitReader ; '
                                    cluster_inner += f'#[doc = "Field `{fname}` writer - {f["description"]}"] pub type {fw} < \'a , REG > = crate :: BitWriter < \'a , REG > ; '
                                else:
                                    cluster_inner += f'#[doc = "Field `{fname}` reader - {f["description"]}"] pub type {fr} = crate :: FieldReader ; '
                                    cluster_inner += f'#[doc = "Field `{fname}` writer - {f["description"]}"] pub type {fw} < \'a , REG > = crate :: FieldWriter < \'a , REG , {f["bitWidth_val"]} > ; '
                                # impls
                                # We'll add to R and W impls later, but for simplicity add field accessors inside impl blocks
                            cluster_inner += f'impl R {{ #[doc = "Bit {f["bitOffset_val"]}"] #[inline (always)] pub fn {fa.lower()} (& self) -> {fr} {{ {fr} :: new ((self . bits & 1) != 0) }} }} '
                            cluster_inner += f'impl W {{ #[doc = "Bit {f["bitOffset_val"]}"] #[inline (always)] pub fn {fa.lower()} (& mut self) -> {fw} < \'_ , {cr_spec} > {{ {fw} :: new (self , {f["bitOffset_val"]}) }} }} '
                            cluster_inner += f'#[doc = "{cr["description"]}"] pub struct {cr_spec} ; impl crate :: RegisterSpec for {cr_spec} {{ type Ux = u32 ; }} '
                            cluster_inner += f'#[doc = "`read()` method returns [`{cr_mod}::R`](R) reader structure"] impl crate :: Readable for {cr_spec} {{ }} '
                            cluster_inner += f'#[doc = "`write(|w| ..)` method takes [`{cr_mod}::W`](W) writer structure"] impl crate :: Writable for {cr_spec} {{ type Safety = crate :: Unsafe ; }} '
                            cluster_inner += ' } '
                        # add cluster mod
                        reg_defs.append(f'#[doc = "{reg["description"]}"] pub mod {cluster_mod_name} {{ #[repr (C)] #[doc = "{reg["description"]}"] #[doc (alias = "{cluster_name}")] pub struct {cluster_type} {{ {cluster_inner} }} impl {cluster_type} {{ }} }}')
                        reg_defs.append(f'#[doc = "{reg["description"]}"] pub use self :: {cluster_mod_name} :: {cluster_type} ;')
                    else:
                        # placeholder
                        rb_fields.append(f'{cluster_accessor} : () ,')
                        rb_impls.append(f'#[doc = "0x{reg["addressOffset_val"]:02x}..0x{reg["addressOffset_val"]+ dim*reg["dimIncrement"]:02x} - {reg["description"]}"]\n#[inline (always)] pub const fn {cluster_accessor} (& self , n : usize) -> & {cluster_type} {{ #[allow (clippy :: no_effect)] [() ; {dim}] [n] ; unsafe {{ & * core :: ptr :: from_ref (self) . cast :: < u8 > () . add ({reg["addressOffset_val"]}) . add ({reg["dimIncrement"]} * n) . cast () }} }}')
                        # iterator
                        rb_impls.append(f'#[doc = "Iterator for array of:"]\n#[doc = "0x{reg["addressOffset_val"]:02x}..0x{reg["addressOffset_val"]+ dim*reg["dimIncrement"]:02x} - {reg["description"]}"]\n#[inline (always)] pub fn {cluster_accessor}_iter (& self) -> impl Iterator < Item = & {cluster_type} > {{ (0 .. {dim}) . map (move | n | unsafe {{ & * core :: ptr :: from_ref (self) . cast :: < u8 > () . add ({reg["addressOffset_val"]}) . add ({reg["dimIncrement"]} * n) . cast () }}) }}')
                        # generate cluster mod similar but for single cluster type
                        cluster_inner = ""
                        for cr in reg["registers"]:
                            cr_name = cr["name"]
                            cr_type2 = apply_ident(cr_name, "register", ident_formats)
                            cr_mod2 = apply_ident(cr_name, "register_mod", ident_formats)
                            cr_spec2 = apply_ident(cr_name, "register_spec", ident_formats)
                            cluster_inner += f'#[doc = "0x00 - {cr["description"]}"] #[inline (always)] pub const fn {cr_mod2} (& self) -> & {cr_type2} {{ & self . {cr_mod2} }} '
                        # For dim cluster, the Cluster struct is single, not array. We'll create mod for cluster.
                        cluster_struct_fields = ""
                        for cr in reg["registers"]:
                            cr_name = cr["name"]
                            cr_type2 = apply_ident(cr_name, "register", ident_formats)
                            cr_mod2 = apply_ident(cr_name, "register_mod", ident_formats)
                            cluster_struct_fields += f'{cr_mod2} : {cr_type2} , '
                        reg_defs.append(f'#[doc = "cluster array"] pub mod {cluster_mod_name} {{ #[repr (C)] #[doc = "cluster array"] #[doc (alias = "{cluster_name}")] pub struct {cluster_type} {{ {cluster_struct_fields} }} impl {cluster_type} {{ {cluster_inner} }} ')
                        # inner register mods
                        for cr in reg["registers"]:
                            cr_name = cr["name"]
                            cr_mod2 = apply_ident(cr_name, "register_mod", ident_formats)
                            cr_spec2 = apply_ident(cr_name, "register_spec", ident_formats)
                            cr_type2 = apply_ident(cr_name, "register", ident_formats)
                            fields_str = ""
                            for f in cr.get("fields",[]):
                                fname = f["name"]
                                fr = apply_ident(fname, "field_reader", ident_formats) if not is_legacy else "BitReader"
                                fw = apply_ident(fname, "field_writer", ident_formats) if not is_legacy else "BitWriter"
                                fa = apply_ident(fname, "field_accessor", ident_formats)
                                fields_str += f'#[doc = "Field `{fname}` reader - {f["description"]}"] pub type {fr} = crate :: BitReader ; '
                                fields_str += f'#[doc = "Field `{fname}` writer - {f["description"]}"] pub type {fw} < \'a , REG > = crate :: BitWriter < \'a , REG > ; '
                            reg_defs.append(f'#[doc = "{cr.get("description","")}"] pub mod {cr_mod2} {{ {fields_str} #[doc = "{cr.get("description","")}"] pub struct {cr_spec2} ; impl crate :: RegisterSpec for {cr_spec2} {{ type Ux = u32 ; }} impl crate :: Readable for {cr_spec2} {{ }} impl crate :: Writable for {cr_spec2} {{ type Safety = crate :: Unsafe ; }} }}')
                            reg_defs[-2] += f'#[doc = "{cr["name"]} (rw) register accessor: {cr["description"]}"] #[doc (alias = "{cr["name"]}")] pub type {cr_type2} = crate :: Reg < {cr_mod2} :: {cr_spec2} > ; '
                        reg_defs[-2] += ' }'
                        reg_defs.append(f'#[doc = "cluster array"] pub use self :: {cluster_mod_name} :: {cluster_type} ;')
                else:
                    # non-dim cluster
                    rb_fields.append(f'{cluster_accessor} : {cluster_type} ,')
                    rb_impls.append(f'#[doc = "0x{reg["addressOffset_val"]:02x} - {reg["description"]}"]\n#[inline (always)] pub const fn {cluster_accessor} (& self) -> & {cluster_type} {{ & self . {cluster_accessor} }}')
                    # cluster mod
                    cluster_fields = ""
                    for cr in reg["registers"]:
                        cr_name = cr["name"]
                        cr_type2 = apply_ident(cr_name, "register", ident_formats) if not is_legacy else cr_name.upper()
                        cr_mod2 = apply_ident(cr_name, "register_mod", ident_formats)
                        cluster_fields += f'{cr_mod2} : {cr_type2} , '
                    reg_defs.append(f'#[doc = "{reg["description"]}"] pub mod {cluster_mod_name} {{ #[repr (C)] #[doc = "{reg["description"]}"] pub struct {cluster_type} {{ {cluster_fields} }} impl {cluster_type} {{ }} }}')
            else:
                # register
                reg_name = reg["name"]
                reg_type = apply_ident(reg_name, "register", ident_formats) if not is_legacy else reg_name.upper()
                reg_mod = apply_ident(reg_name, "register_mod", ident_formats)
                reg_spec = apply_ident(reg_name, "register_spec", ident_formats) if not is_legacy else reg_name.upper() + "_SPEC"
                reg_accessor = apply_ident(reg_name, "register_accessor", ident_formats)
                # handle dim
                dim = reg.get("dim")
                if dim and not keep_list:
                    # array case: need reserved handling? Simplify: generate array field
                    # Calculate offset: reg address offset
                    # For array, generate field like reg : [Reg ; dim]
                    # Need to handle reserved gaps before next register? For simplicity, just generate array field without reserved.
                    rb_fields.append(f'{reg_accessor} : [{reg_type} ; {dim}] ,')
                    rb_impls.append(f'#[doc = "0x{reg["addressOffset_val"]:02x}..0x{reg["addressOffset_val"]+ dim*reg["dimIncrement"]:02x} - {reg["description"]}"]\n#[inline (always)] pub const fn {reg_accessor} (& self , n : usize) -> & {reg_type} {{ & self . {reg_accessor} [n] }}')
                    rb_impls.append(f'#[doc = "Iterator for array of:"]\n#[doc = "0x{reg["addressOffset_val"]:02x}..0x{reg["addressOffset_val"]+ dim*reg["dimIncrement"]:02x} - {reg["description"]}"]\n#[inline (always)] pub fn {reg_accessor}_iter (& self) -> impl Iterator < Item = & {reg_type} > {{ self . {reg_accessor} . iter () }}')
                    # register definition for array: single mod for REG
                    # But name is like REG%s -> need to handle?
                    # For dim, name contains %s, we should keep as is? Original for REG%s gave reg with dim
                    # We'll just use reg_mod as base without %s
                    clean_mod = reg_mod.replace("%s","").lower() if "%s" in reg_mod else reg_mod
                    clean_type = reg_type.replace("%s","") if "%s" in reg_type else reg_type
                    clean_spec = reg_spec.replace("%s","") if "%s" in reg_spec else reg_spec
                    desc = reg.get("description","")
                    # generate register alias type and mod
                    reg_defs.append(f'#[doc = "{reg_name} (rw) register accessor: {desc}"]\n#[doc (alias = "{reg_name}")] pub type {clean_type} = crate :: Reg < {clean_mod} :: {clean_spec} > ;')
                    # fields
                    fields_def = ""
                    r_impl = ""
                    w_impl = ""
                    for f in reg.get("fields",[]):
                        fname = f["name"]
                        # apply field ident formats
                        fr = apply_ident(fname, "field_reader", ident_formats) if not is_legacy else "BitReader"
                        fw = apply_ident(fname, "field_writer", ident_formats) if not is_legacy else "BitWriter"
                        fa = apply_ident(fname, "field_accessor", ident_formats)
                        if f["bitWidth_val"] == 1:
                            fields_def += f'#[doc = "Field `{fname}` reader - {f.get("description","")}"] pub type {fr} = crate :: BitReader ; '
                            fields_def += f'#[doc = "Field `{fname}` writer - {f.get("description","")}"] pub type {fw} < \'a , REG > = crate :: BitWriter < \'a , REG > ; '
                            r_impl += f'#[doc = "Bit {f["bitOffset_val"]}"]\n#[inline (always)] pub fn {fa} (& self) -> {fr} {{ {fr} :: new ((self . bits & 1) != 0) }} '
                            w_impl += f'#[doc = "Bit {f["bitOffset_val"]}"]\n#[inline (always)] pub fn {fa} (& mut self) -> {fw} < \'_ , {clean_spec} > {{ {fw} :: new (self , {f["bitOffset_val"]}) }} '
                        else:
                            fields_def += f'#[doc = "Field `{fname}` reader - {f.get("description","")}"] pub type {fr} = crate :: FieldReader ; '
                            fields_def += f'#[doc = "Field `{fname}` writer - {f.get("description","")}"] pub type {fw} < \'a , REG > = crate :: FieldWriter < \'a , REG , {f["bitWidth_val"]} > ; '
                            r_impl += f'#[doc = "Bits {f["bitOffset_val"]}:{f["bitOffset_val"]+f["bitWidth_val"]-1}"]\n#[inline (always)] pub fn {fa} (& self) -> {fr} {{ {fr} :: new ((self . bits >> {f["bitOffset_val"]}) & { (1<<f["bitWidth_val"])-1 }) }} '
                            w_impl += f'#[doc = "Bits {f["bitOffset_val"]}:{f["bitOffset_val"]+f["bitWidth_val"]-1}"]\n#[inline (always)] pub fn {fa} (& mut self) -> {fw} < \'_ , {clean_spec} > {{ {fw} :: new (self , {f["bitOffset_val"]}) }} '
                    # Choose Debug impl based on impl_debug flag
                    debug_impl = ""
                    if impl_debug:
                        if impl_debug_feature:
                            debug_impl = f'#[cfg (feature = "{impl_debug_feature}")] impl core :: fmt :: Debug for R {{ fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result {{ f . debug_struct ("{reg_name}") . finish () }} }}'
                        else:
                            debug_impl = f'impl core :: fmt :: Debug for R {{ fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result {{ write ! (f , "{{}}" , self . bits ()) }} }}'
                    # defmt
                    defmt_attr = ""
                    if impl_defmt:
                        defmt_attr = f'#[cfg_attr (feature = "{impl_defmt}" , derive (defmt :: Format))]'
                    reg_defs.append(f'#[doc = "{desc}"] pub mod {clean_mod} {{ #[doc = "Register `{reg_name}` reader"] pub type R = crate :: R < {clean_spec} > ; #[doc = "Register `{reg_name}` writer"] pub type W = crate :: W < {clean_spec} > ; {fields_def} {debug_impl} impl R {{ {r_impl} }} impl W {{ {w_impl} }} {defmt_attr} #[doc = "{desc}"] pub struct {clean_spec} ; impl crate :: RegisterSpec for {clean_spec} {{ type Ux = u32 ; }} #[doc = "`read()` method returns [`{clean_mod}::R`](R) reader structure"] impl crate :: Readable for {clean_spec} {{ }} #[doc = "`write(|w| ..)` method takes [`{clean_mod}::W`](W) writer structure"] impl crate :: Writable for {clean_spec} {{ type Safety = crate :: Unsafe ; }} }}')
                elif dim and keep_list:
                    # keep list: generate separate registers reg0, reg1 etc
                    for idx in range(dim):
                        field_name = f"{reg_accessor}{idx}"
                        rb_fields.append(f'{field_name} : {reg_type} ,')
                        rb_impls.append(f'#[doc = "0x{reg["addressOffset_val"]+ idx*reg["dimIncrement"]:02x} - {reg["description"]}"]\n#[inline (always)] pub const fn {field_name} (& self) -> & {reg_type} {{ & self . {field_name} }}')
                    # generate single mod for register type (same as above but without array)
                    clean_mod = reg_mod.replace("%s","").lower() if "%s" in reg_mod else reg_mod
                    clean_type = reg_type.replace("%s","") if "%s" in reg_type else reg_type
                    clean_spec = reg_spec.replace("%s","") if "%s" in reg_spec else reg_spec
                    desc = reg.get("description","")
                    reg_defs.append(f'#[doc = "{reg_name} (rw) register accessor: {desc}"]\n#[doc (alias = "{reg_name}")] pub type {clean_type} = crate :: Reg < {clean_mod} :: {clean_spec} > ;')
                    fields_def = ""
                    r_impl = ""
                    w_impl = ""
                    for f in reg.get("fields",[]):
                        fname = f["name"]
                        fr = apply_ident(fname, "field_reader", ident_formats)
                        fw = apply_ident(fname, "field_writer", ident_formats)
                        fa = apply_ident(fname, "field_accessor", ident_formats)
                        if f["bitWidth_val"] == 1:
                            fields_def += f'#[doc = "Field `{fname}` reader - {f.get("description","")}"] pub type {fr} = crate :: BitReader ; '
                            fields_def += f'#[doc = "Field `{fname}` writer - {f.get("description","")}"] pub type {fw} < \'a , REG > = crate :: BitWriter < \'a , REG > ; '
                            r_impl += f'#[doc = "Bit {f["bitOffset_val"]}"]\n#[inline (always)] pub fn {fa} (& self) -> {fr} {{ {fr} :: new ((self . bits & 1) != 0) }} '
                            w_impl += f'#[doc = "Bit {f["bitOffset_val"]}"]\n#[inline (always)] pub fn {fa} (& mut self) -> {fw} < \'_ , {clean_spec} > {{ {fw} :: new (self , {f["bitOffset_val"]}) }} '
                    reg_defs.append(f'#[doc = "{desc}"] pub mod {clean_mod} {{ #[doc = "Register `{reg_name}` reader"] pub type R = crate :: R < {clean_spec} > ; #[doc = "Register `{reg_name}` writer"] pub type W = crate :: W < {clean_spec} > ; {fields_def} impl R {{ {r_impl} }} impl W {{ {w_impl} }} #[doc = "{desc}"] pub struct {clean_spec} ; impl crate :: RegisterSpec for {clean_spec} {{ type Ux = u32 ; }} impl crate :: Readable for {clean_spec} {{ }} impl crate :: Writable for {clean_spec} {{ type Safety = crate :: Unsafe ; }} }}')
                else:
                    # normal register
                    rb_fields.append(f'{reg_accessor} : {reg_type} ,')
                    rb_impls.append(f'#[doc = "0x{reg["addressOffset_val"]:02x} - {reg["description"]}"]\n#[inline (always)] pub const fn {reg_accessor} (& self) -> & {reg_type} {{ & self . {reg_accessor} }}')
                    # register definition
                    # Need to handle ignore_groups? If ignore_groups false, prefix with alternateGroup? Not needed.
                    alias_doc = f'#[doc (alias = "{reg_name}")]'
                    # For register with access, determine readable/writable
                    readable = reg["access"] in ("read-only","read-write")
                    writable = reg["access"] in ("write-only","read-write")
                    # Build field types
                    fields_def = ""
                    r_impl = ""
                    w_impl = ""
                    for f in reg.get("fields",[]):
                        fname = f["name"]
                        # field ident formatting
                        # default for field_reader is Pascal+R, field_writer Pascal+W, field_accessor snake
                        if is_legacy:
                            fr = f"{fname.upper()}_R"
                            fw = f"{fname.upper()}_W"
                            fa = fname.lower()
                        else:
                            fr = apply_ident(fname, "field_reader", ident_formats)  # default adds R
                            # For field_reader, default is something like EnableR, but our apply already includes suffix?
                            # Our earlier default for field_reader gave "pascal" + "R", but we implemented apply to add suffix via defaults.
                            # So for ENABLE, apply with field_reader should give EnableR.
                            # Let's ensure: field_reader default suffix is "R", field_writer "W"
                            # Our apply for field_reader will return EnableR, etc.
                            fw = apply_ident(fname, "field_writer", ident_formats)
                            fa = apply_ident(fname, "field_accessor", ident_formats)
                        # Determine if bit or field
                        if f["bitWidth_val"] == 1:
                            fields_def += f'#[doc = "Field `{fname}` reader - {f.get("description","")}"] pub type {fr} = crate :: BitReader ; '
                            fields_def += f'#[doc = "Field `{fname}` writer - {f.get("description","")}"] pub type {fw} < \'a , REG > = crate :: BitWriter < \'a , REG > ; '
                            r_impl += f'#[doc = "Bit {f["bitOffset_val"]}"]\n#[inline (always)] pub fn {fa} (& self) -> {fr} {{ {fr} :: new ((self . bits & 1) != 0) }} '
                            w_impl += f'#[doc = "Bit {f["bitOffset_val"]}"]\n#[inline (always)] pub fn {fa} (& mut self) -> {fw} < \'_ , {reg_spec} > {{ {fw} :: new (self , {f["bitOffset_val"]}) }} '
                        else:
                            bits_mask = (1<<f["bitWidth_val"])-1
                            fields_def += f'#[doc = "Field `{fname}` reader - {f.get("description","")}"] pub type {fr} = crate :: FieldReader ; '
                            fields_def += f'#[doc = "Field `{fname}` writer - {f.get("description","")}"] pub type {fw} < \'a , REG > = crate :: FieldWriter < \'a , REG , {f["bitWidth_val"]} > ; '
                            r_impl += f'#[doc = "Bits {f["bitOffset_val"]}:{f["bitOffset_val"]+f["bitWidth_val"]-1}"]\n#[inline (always)] pub fn {fa} (& self) -> {fr} {{ {fr} :: new (((self . bits >> {f["bitOffset_val"]}) & {bits_mask}) as u8) }} '
                            w_impl += f'#[doc = "Bits {f["bitOffset_val"]}:{f["bitOffset_val"]+f["bitWidth_val"]-1}"]\n#[inline (always)] pub fn {fa} (& mut self) -> {fw} < \'_ , {reg_spec} > {{ {fw} :: new (self , {f["bitOffset_val"]}) }} '
                    # Build reg mod
                    # Access docs
                    access_str = reg["access"]
                    # For rw register, docs say (rw) etc.
                    # Determine readable/writable docs
                    doc_access = f"({access_str})"
                    # Create register type alias
                    reg_defs.append(f'#[doc = "{reg_name} {doc_access} register accessor: {reg["description"]}\\n\\nYou can [`read`](crate::Reg::read) this register and get [`{reg_mod}::R`]. You can [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{reg_mod}::W`]. You can also [`modify`](crate::Reg::modify) this register. See [API](https://docs.rs/svd2rust/#read--modify--write-api).\\n\\nFor information about available fields see [`mod@{reg_mod}`] module"]\n{alias_doc} pub type {reg_type} = crate :: Reg < {reg_mod} :: {reg_spec} > ;')
                    # defmt etc
                    defmt_attr = ""
                    if impl_defmt:
                        defmt_attr = f'#[cfg_attr (feature = "{impl_defmt}" , derive (defmt :: Format))]'
                    # impl_debug handling for R/W
                    debug_r = ""
                    debug_w = ""
                    if impl_debug:
                        if impl_debug_feature:
                            debug_r = f'#[cfg_attr (feature = "{impl_debug_feature}" , derive (Debug))] impl core :: fmt :: Debug for R {{ fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result {{ f . debug_struct ("{reg_name}") . field ("{reg_name.lower()}" , & self . bits) . finish () }} }}'
                        else:
                            # simple debug
                            debug_r = f'impl core :: fmt :: Debug for R {{ fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result {{ write ! (f , "{{}}" , self . bits ()) }} }}'
                    reg_defs.append(f'#[doc = "{reg["description"]}"] pub mod {reg_mod} {{ {fields_def} #[doc = "Register `{reg_name}` reader"] pub type R = crate :: R < {reg_spec} > ; #[doc = "Register `{reg_name}` writer"] pub type W = crate :: W < {reg_spec} > ; {debug_r} impl R {{ {r_impl} }} impl W {{ {w_impl} }} {defmt_attr} #[doc = "\\n\\nYou can [`read`](crate::Reg::read) this register and get [`{reg_mod}::R`](R). You can [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{reg_mod}::W`](W). You can also [`modify`](crate::Reg::modify) this register. See [API](https://docs.rs/svd2rust/#read--modify--write-api)."] pub struct {reg_spec} ; impl crate :: RegisterSpec for {reg_spec} {{ type Ux = u32 ; }} '
                    # Add Readable/Writable impls based on access
                    if readable:
                        reg_defs[-1] += f'#[doc = "`read()` method returns [`{reg_mod}::R`](R) reader structure"] impl crate :: Readable for {reg_spec} {{ }} '
                    if writable:
                        reg_defs[-1] += f'#[doc = "`write(|w| ..)` method takes [`{reg_mod}::W`](W) writer structure"] impl crate :: Writable for {reg_spec} {{ type Safety = crate :: Unsafe ; }} '
                    reg_defs[-1] += ' }'

        # Build peripheral mod section
        # For RegisterBlock, we need to generate struct with fields as built
        # If no registers, maybe empty?
        rb_fields_str = ' '.join(rb_fields)
        rb_impls_str = ' '.join(rb_impls)
        periph_mod_content = f'#[repr (C)]\n#[doc = "Register block"] pub struct RegisterBlock {{ {rb_fields_str} }} impl RegisterBlock {{ {rb_impls_str} }} '
        # Add register definitions
        periph_mod_content += ' '.join(reg_defs)
        periph_section = f'{cfg_feature}#[doc = "{periph_name}"] pub type {periph_type} = crate :: Periph < {periph_spec} > ; {cfg_feature}pub struct {periph_spec} ; {cfg_feature}impl crate :: PeripheralSpec for {periph_spec} {{ type RB = {periph_mod} :: RegisterBlock ; const ADDRESS : usize = 0x{ p["baseAddress"]:08x} ; const NAME : & \'static str = "{periph_name}" ; }} {cfg_feature}#[doc = "{periph_name}"] pub mod {periph_mod} {{ {periph_mod_content} }}'
        periph_sections.append(periph_section)

    # Build Peripherals struct
    peripherals_decl = ' '.join([f'#[doc = "{p["name"]}"] pub {apply_ident(p["name"], "peripheral_singleton", ident_formats)} : {apply_ident(p["name"], "peripheral", ident_formats)} ,' for p in device["peripherals"]])
    peripherals_take = ' '.join([f'{apply_ident(p["name"], "peripheral_singleton", ident_formats)} : {apply_ident(p["name"], "peripheral", ident_formats)} :: steal () ,' for p in device["peripherals"]])
    # Feature cfg for peripherals struct fields?
    # If feature_peripheral, fields are cfg gated
    if feature_peripheral:
        # rebuild with cfg
        peripherals_decl = ' '.join([f'#[cfg (feature = "{apply_ident(p["name"], "peripheral_feature", ident_formats).lower()}")] #[doc = "{p["name"]}"] pub {apply_ident(p["name"], "peripheral_singleton", ident_formats)} : {apply_ident(p["name"], "peripheral", ident_formats)} ,' for p in device["peripherals"]])
