def build_generic_inner(atomics, atomics_feature=None, edition="2021"):
    inner = GENERIC_INNER
    if atomics:
        # add atomic mod
        if atomics_feature:
            atomic_code = f'#[cfg (feature = "{atomics_feature}")] ' + GENERIC_ATOMIC_SUFFIX
        else:
            atomic_code = GENERIC_ATOMIC_SUFFIX
        # need to close the generic mod? The inner already ends with } for the Reg impl, we append atomic mod before final }
        # In original, atomic mod is inside generic mod after Reg impl
        # Our GENERIC_INNER ends with } } (closing pub mod generic). Let's append before final }
        # Simplify: just append atomic_code before final }
        inner = inner.rstrip()
        if inner.endswith("}"):
            inner = inner[:-1] + atomic_code + " }"
        else:
            inner = inner + atomic_code
    return inner

def main():
    import sys
    argv = sys.argv[1:]
    # quick help/version handling before full parsing? Need to handle -h/--help, -V/--version
    # But need to handle clap errors first? In clap, help takes precedence over errors? Actually if help flag present, it prints help even if other errors? We'll replicate simple: if help or version in argv, print and exit 0 regardless of other args.
    # Check for help/version
    has_help_long = "--help" in argv
    has_help_short = "-h" in argv
    has_version_long = "--version" in argv
    has_version_short = "-V" in argv
    if has_help_long or has_help_short:
        if has_help_long:
            print(LONG_HELP, end="")
        else:
            print(SHORT_HELP, end="")
        sys.exit(0)
    if has_version_long or has_version_short:
        print(VERSION)
        sys.exit(0)

    # define parsing
    # mapping for options that take values
    # We need to handle both -o and --output-dir etc as same dest
    # Create sets
    bool_flags = {
        "--atomics": "atomics",
        "--ignore-groups": "ignore_groups",
        "--keep-list": "keep_list",
        "-g": "generic_mod",
        "--generic-mod": "generic_mod",
        "--feature-group": "feature_group",
        "--feature-peripheral": "feature_peripheral",
        "--field-names-for-enums": "field_names_for_enums",
        "--max-cluster-size": "max_cluster_size",
        "--impl-debug": "impl_debug",
        "-m": "make_mod",
        "--make-mod": "make_mod",
        "--skip-crate-attributes": "skip_crate_attributes",
        "-s": "strict",
        "--strict": "strict",
        "--reexport-core-peripherals": "reexport_core_peripherals",
        "--reexport-interrupt": "reexport_interrupt",
    }
    value_flags = {
        "-i": "input",
        "--input": "input",
        "-o": "output_dir",
        "--output-dir": "output_dir",
        "-c": "config",
        "--config": "config",
        "--settings": "settings",
        "--edition": "edition",
        "--target": "target",
        "--atomics-feature": "atomics_feature",
        "-f": "ident_format",
        "--ident-format": "ident_format",
        "--ident-formats-theme": "ident_formats_theme",
        "--impl-debug-feature": "impl_debug_feature",
        "--impl-defmt": "impl_defmt",
        "--source-type": "source_type",
        "-b": "base_address_shift",
        "--base-address-shift": "base_address_shift",
        "-l": "log_level",
        "--log": "log_level",
    }
    # For tracking duplicates
    seen = {}
    config = {
        "atomics": False,
        "ignore_groups": False,
        "keep_list": False,
        "generic_mod": False,
        "feature_group": False,
        "feature_peripheral": False,
        "field_names_for_enums": False,
        "max_cluster_size": False,
        "impl_debug": False,
        "make_mod": False,
        "skip_crate_attributes": False,
        "strict": False,
        "reexport_core_peripherals": False,
        "reexport_interrupt": False,
        "edition": None,
        "target": None,
        "atomics_feature": None,
        "ident_format": [],
        "ident_formats_theme": None,
        "impl_debug_feature": None,
        "impl_defmt": None,
        "source_type": None,
        "base_address_shift": None,
        "log_level": None,
        "input": None,
        "output_dir": None,
        "config": None,
        "settings": None,
    }
    # need to handle value_flags with short and long aliases counting as same dest for duplicate check
    # seen dest -> count
    seen_dest = {}
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg in bool_flags:
            dest = bool_flags[arg]
            # check duplicate for bool? bool duplicates should not error? In clap, using same flag twice is okay? But for bool, multiple times not error.
            # For value flags, duplicate should error.
            config[dest] = True
            i += 1
        elif arg in value_flags:
            dest = value_flags[arg]
            # check if next arg exists and not starting with -? But values can start with -? For -i, file path may not start with -, so we treat next as value even if starts with -? Clap would treat next as value if not another known flag? Simpler: require next arg exists.
            if i+1 >= len(argv):
                # error: a value is required
                # Need to find original flag representation for message
                # For -i, message is "error: a value is required for '-i <FILE>' but none was supplied"
                # For -o, it's for '--output-dir <PATH>' ?
                # Let's map flag to placeholder
                placeholder = {
                    "-i": "'-i <FILE>'",
                    "-o": "'--output-dir <PATH>'",
                    "--output-dir": "'--output-dir <PATH>'",
                    "-c": "'--config <TOML_FILE>'",
