                    "--base-address-shift": "'--base-address-shift <base_address_shift>'",
                    "-l": "'--log <log_level>'",
                    "--log": "'--log <log_level>'",
                }.get(arg, f"'{arg} <value>'")
                print(f"error: a value is required for {placeholder} but none was supplied\n\nFor more information, try '--help'.", file=sys.stderr)
                sys.exit(2)
            val = argv[i+1]
            # For dest that allows multiple (ident_format), allow duplicate
            if dest != "ident_format":
                if dest in seen_dest and seen_dest[dest] >= 1:
                    # error duplicate
                    # Find flag name for message: use long form if available
                    long_name = {
